-- 数据源: 生辰八字.xlsx sha256=57a26df309b769d723cc8da8afb4fb6f6a90561b0857c8bae07c5e1289d49eb9
-- DDL 来源: Room 导出 schema

CREATE TABLE IF NOT EXISTS `stock` (`id` INTEGER NOT NULL, `code` TEXT NOT NULL, `symbol` TEXT NOT NULL, `name` TEXT NOT NULL, `exchange` TEXT NOT NULL, `board` TEXT NOT NULL, `listing_date` TEXT NOT NULL, `first_open` REAL, `first_close` REAL, `first_change` REAL, `first_day_flag` TEXT NOT NULL, `industry` TEXT NOT NULL, `industry_full` TEXT NOT NULL, `stock_nature` TEXT NOT NULL, PRIMARY KEY(`id`));
CREATE UNIQUE INDEX IF NOT EXISTS `index_stock_code` ON `stock` (`code`);
CREATE INDEX IF NOT EXISTS `index_stock_name` ON `stock` (`name`);
CREATE INDEX IF NOT EXISTS `index_stock_symbol` ON `stock` (`symbol`);
CREATE INDEX IF NOT EXISTS `index_stock_listing_date` ON `stock` (`listing_date`);
CREATE TABLE IF NOT EXISTS `stock_bazi` (`stock_id` INTEGER NOT NULL, `full_bazi` TEXT NOT NULL, `year_pillar` TEXT NOT NULL, `month_pillar` TEXT NOT NULL, `day_pillar` TEXT NOT NULL, `hour_pillar` TEXT NOT NULL, `year_stem` TEXT NOT NULL, `year_branch` TEXT NOT NULL, `month_stem` TEXT NOT NULL, `month_branch` TEXT NOT NULL, `day_stem` TEXT NOT NULL, `day_branch` TEXT NOT NULL, `hour_stem` TEXT NOT NULL, `hour_branch` TEXT NOT NULL, `day_master_element` TEXT NOT NULL, `month_season_element` TEXT NOT NULL, `na_yin` TEXT NOT NULL, `day_master_strength` TEXT NOT NULL, PRIMARY KEY(`stock_id`));
CREATE INDEX IF NOT EXISTS `index_stock_bazi_day_stem` ON `stock_bazi` (`day_stem`);
CREATE INDEX IF NOT EXISTS `index_stock_bazi_day_pillar` ON `stock_bazi` (`day_pillar`);
CREATE INDEX IF NOT EXISTS `index_stock_bazi_year_pillar` ON `stock_bazi` (`year_pillar`);
CREATE INDEX IF NOT EXISTS `index_stock_bazi_month_pillar` ON `stock_bazi` (`month_pillar`);
CREATE TABLE IF NOT EXISTS `stock_hidden_ten_god` (`stock_id` INTEGER NOT NULL, `pillar` TEXT NOT NULL, `branch` TEXT NOT NULL, `hidden_stem` TEXT NOT NULL, `ten_god` TEXT NOT NULL, `rank` TEXT NOT NULL, PRIMARY KEY(`stock_id`, `pillar`, `hidden_stem`));
CREATE INDEX IF NOT EXISTS `index_stock_hidden_ten_god_ten_god_stock_id` ON `stock_hidden_ten_god` (`ten_god`, `stock_id`);
CREATE TABLE IF NOT EXISTS `ganzhi_calendar` (`date` TEXT NOT NULL, `year_ganzhi` TEXT NOT NULL, `month_ganzhi` TEXT NOT NULL, `day_ganzhi` TEXT NOT NULL, `year_stem` TEXT NOT NULL, `year_branch` TEXT NOT NULL, `month_stem` TEXT NOT NULL, `month_branch` TEXT NOT NULL, `day_stem` TEXT NOT NULL, `day_branch` TEXT NOT NULL, `month_branch_label` TEXT NOT NULL, `solar_term` TEXT, PRIMARY KEY(`date`));
CREATE TABLE IF NOT EXISTS `trade_calendar` (`date` TEXT NOT NULL, `is_trade_day` INTEGER NOT NULL, `weekday` INTEGER NOT NULL, `closed_reason` TEXT, `confidence` TEXT NOT NULL, PRIMARY KEY(`date`));
CREATE TABLE IF NOT EXISTS `scan_cache` (`stock_id` INTEGER NOT NULL, `date` TEXT NOT NULL, `year_ten_god` TEXT NOT NULL, `month_ten_god` TEXT NOT NULL, `day_ten_god` TEXT NOT NULL, `wealth_type` TEXT NOT NULL, `is_trade_day` INTEGER NOT NULL, `computed_at` INTEGER NOT NULL, PRIMARY KEY(`stock_id`, `date`));
CREATE TABLE IF NOT EXISTS `favorite` (`stock_id` INTEGER NOT NULL, `added_at` INTEGER NOT NULL, PRIMARY KEY(`stock_id`));
CREATE TABLE IF NOT EXISTS `app_meta` (`key` TEXT NOT NULL, `value` TEXT NOT NULL, PRIMARY KEY(`key`));
PRAGMA user_version = 1;
